async function economicSnapshot(ctx:Context,b:Data){ensure(b.sourceRecordId===b.programId,'Select this coordination programme',409);const p=(await policyFor(ctx,b.policyId,b.programId)).value,out=(await records(ctx,'commitment')).filter(r=>r.data.programId===b.programId),incoming=(await records(ctx,'incoming-contribution')).filter(r=>r.data.programId===b.programId),all=[...out,...incoming];ensure(all.every(r=>r.data.terms.currency===p.currency),'A financial programme cannot consolidate different original currencies',409);const confirmed=new Set((await ctx.db.query("SELECT commitment_id FROM synthetic_settlements WHERE state='confirmed'")).rows.map(r=>r.commitment_id));const approved=out.filter(r=>r.data.contributorApproved===true&&!['cancelled','rejected'].includes(r.data.status)),accepted=incoming.filter(r=>r.data.acceptedAt&&r.data.status!=='cancelled'),cash=(rows:RecordValue[])=>exactSum(rows.filter(r=>r.data.terms.resourceKind==='cash').map(r=>r.data.terms.amountCents));const programme=await get(ctx,'program',b.programId),observedAt=(await ctx.db.query("SELECT max(updated_at) at FROM business_records WHERE kind IN ('commitment','incoming-contribution') AND data->>'programId'=$1",[b.programId])).rows[0].at?.toISOString()??programme.data.createdAt;return{currency:p.currency,periodStart:programme.data.createdAt,periodEnd:observedAt,validUntil:p.validUntil,metrics:{type:'resource-coordination',outgoingCommittedCents:cash(approved),confirmedOutgoingCents:cash(out.filter(r=>confirmed.has(r.data.terms.commitmentId))),reconciledOutgoingCents:cash(out.filter(r=>confirmed.has(r.data.terms.commitmentId)&&r.data.status==='reconciled')),incomingAcceptedCents:cash(accepted),incomingReceivedCents:cash(incoming.filter(r=>r.data.receiptId&&r.data.resourceKind==='cash')),pendingCount:all.filter(r=>!['reconciled','received','cancelled','rejected','returned'].includes(r.data.status)).length,unreconciledCount:all.filter(r=>['pending-settlement','settlement-uncertain','receipt-pending','settled','receipt-recording-pending','settlement-observed'].includes(r.data.status)).length,disputedCount:all.filter(r=>r.data.status==='disputed').length,noncashDeliveryCount:all.filter(r=>r.data.terms.resourceKind!=='cash'&&r.data.deliveryId).length,noncashReturnedCount:all.filter(r=>r.data.returnedAt||r.data.status==='returned').length,additionalEcosystemIncomeCents:0},sourceReferences:[{entityId:missionEntity(ctx),installationId:ctx.installationId,moduleId,streamId:'private-coordination-programmes',recordId:b.programId,revision:programme.revision,observedAt,classification:'allocation',synthetic:true}]};}
export function resourceCoordination(manifest:ModulePackageManifest):Definition{return financeDefinition(moduleId,manifest,{resources,actions,receive,acknowledge,economicSnapshot,economicSources:async ctx=>(await financeVisible(ctx,'program')).map(r=>({id:r.id,name:r.data.name})),tick:async ctx=>{let changed=0;for(const r of await records(ctx,'commitment')){if(changed>=4)break;if(['pending-settlement','pending-resource'].includes(r.data.status)&&Date.parse(r.data.pendingSince)<Date.now()-30000){await coordinationChange(ctx,r,{status:r.data.status==='pending-resource'?'resource-uncertain':'settlement-uncertain',lastFailure:'The original resource debit has no confirmed receipt. Reconcile its original identity; no second instruction was created.'},'financial.timeout-requires-reconciliation');changed++;}else if(r.data.status==='authorization-check'&&Date.parse(r.data.authorizationRequestedAt)<Date.now()-45000){await coordinationChange(ctx,r,{status:'authorization-expired',lastFailure:'Receiving authorization was not confirmed in time. Reauthorization is required before execution.'},'financial.authorization-timeout');changed++;}}},queries:[{path:'/dispatch-authority',run:async(ctx,q)=>{const id=q?.q;ensure(typeof id==='string'&&new RegExp(uuid.pattern).test(id),'Invalid dispatch identity',400);const d=(await ctx.db.query('SELECT * FROM economic_dispatch WHERE command_id=$1',[id])).rows[0];ensure(d,'Financial dispatch unavailable',403);await requireProgramAccess(ctx,d.program_id,'program.manage');await requireProgramAccess({...ctx,actor:d.actor_id},d.program_id,d.permission);const r=await get(ctx,(await ctx.db.query('SELECT kind FROM business_records WHERE id=$1',[d.audience.originRecordId])).rows[0].kind,d.audience.originRecordId),c=(await ctx.db.query('SELECT envelope FROM integration_outbox WHERE command_id=$1',[id])).rows[0].envelope;if(d.permission==='finance.execute'){const p=await approvedSource(ctx,r),executor=await authorityGrant({...ctx,actor:d.actor_id},r.data.programId,p,'executor');ensure(executor.limitCents>=(r.data.terms.resourceKind==='cash'?r.data.amountCents:r.data.terms.valuationCents??p.approvalLimitCents),'Execution delegation revoked or exceeded',403);if(c.command==='finance.resource.consume')ensure(Date.parse(c.payload.receiverPermitExpiresAt)>Date.now(),'Receiving execution authorization expired',403);}if(c.command==='finance.budget.cancel'){const p=(await policyFor(ctx,r.data.receiverPolicyId,r.data.programId)).value;ensure((await financialReviewCount(ctx,r,p,{termsDigest:r.data.termsDigest,purpose:'cancel'})).complete,'Current cancellation review quorum required',403);await authorityGrant({...ctx,actor:d.actor_id},r.data.programId,p,'receiver');}if(c.command==='finance.budget.accept'){const p=await approvedReceiver(ctx,r);await authorityGrant({...ctx,actor:d.actor_id},r.data.programId,p,'receiver');}return{authorized:true,commandId:id,commandDigest:d.command_digest,...d.audience};}},{path:'/coordination-overview',run:async ctx=>({records:[...(await financeVisible(ctx,'commitment')),...(await financeVisible(ctx,'incoming-contribution'))].map(r=>({id:r.id,code:r.data.code,direction:r.kind==='commitment'?'outgoing':'incoming',status:r.data.status,lastFailure:r.data.lastFailure??null,currency:r.data.terms.currency,amountCents:r.data.amountCents,resourceKind:r.data.terms.resourceKind,quantity:r.data.quantity,unit:r.data.terms.unit,restriction:r.data.terms.restriction,settlementId:r.data.settlementId??null,received:r.data.status==='received'||r.data.status==='reconciled',additionalEcosystemIncomeCents:0,synthetic:true}))})}]});}
